def format_bytes(n):
    """Return a human-readable size string, e.g. '1.5 KB'."""
    units = ['B', 'KB', 'MB', 'GB', 'TB', 'PB']
    size = float(n)
    for unit in units:
        if size < 1024 or unit == units[-1]:
            if unit == 'B':
                return f'{int(size)} {unit}'
            return f'{size:.1f} {unit}'
